const r=n=>{if(typeof n!="string"&&typeof n!="number")return null;const t=Date.parse(String(n));return Number.isFinite(t)?t:null},u=(n,t=Date.now())=>{if(!n)return"unknown";const e=String(n.status??"").toLowerCase();if(e==="cancelled")return"cancelled";if(e==="completed")return"completed";const s=r(n.start_time),o=r(n.end_time);return s!==null&&t<s?"upcoming":s!==null&&o!==null&&t>=s&&t<o?"live":o!==null&&t>=o?"grading":"unknown"},i=(n,t)=>{const e=r(n);return e!==null&&t>=e+12e4},l=n=>{const t=r(n);return t===null?0:t-Date.now()},c=(n,t)=>{const e=r(n);return e===null?0:Math.max(0,Math.ceil((e-t)/1e3))};export{l as a,u as d,i,c as s};
